window.kbPageData["views/entry/k-cd27115c75d73688"] = {"key":"entry/k-cd27115c75d73688","state":{"route":"entry/k-cd27115c75d73688"},"node":{"id":"k-cd27115c75d73688","mode":"k","title":"统筹发展和安全","type":"观点与论证","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":[],"qs":["政治理论必刷100题#50","国考 2025 行政执法 行测#20"],"current":true,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"repeatPositions":0,"reviewSet":"多题条目","independentCount":2,"tags":{"专题":["modern"],"主类":["观点与论证"],"出处性质":["专项题干","机构注释"],"学科":["政治理论"],"来源主题":["党政制度与理论"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"统筹发展和安全，是指在谋划和推进发展时兼顾风险防范和安全保障，使高质量发展与高水平安全相互促进。","review":{"title":"统筹发展和安全","type":"观点与论证","definition":"统筹发展和安全，是指在谋划和推进发展时兼顾风险防范和安全保障，使高质量发展与高水平安全相互促进。","explanation":"2025年4月30日关于谋划“十五五”的座谈会要求通盘考虑内外部风险挑战，健全国家安全体系、增强维护安全能力，以高效能治理促进发展和安全良性互动。2024年4月23日新时代推动西部大开发座谈会把这一要求落实到提升能源资源等重点领域的安全保障能力。","basis":"据关联原题及所列出处编释。","references":[{"source":"run","location":"统筹发展和安全"}],"examFocus":{"政治理论必刷100题#50":"根据谋划“十五五”时期经济社会发展的座谈会讲话，区分发展与安全的关系、价值取向、战略重点和产业布局。","国考 2025 行政执法 行测#20":"对照新时代西部大开发的部署，核对产业转型、对内对外开放、安全保障和城乡融合的要求。"}},"aspects":[{"title":"“十五五”谋划中的高效能治理","uses":[{"unit":"Q1","role":"直接考查","use":"本题为选非题。A项所述高效能治理要求符合座谈会讲话。C项误将应摆在更加突出战略位置的“因地制宜发展新质生产力”表述为“推动高质量发展”，故选C。","evidence":"要更加注重统筹发展和安全，以高效能治理促进高质量发展和高水平安全良性互动","qids":["政治理论必刷100题#50"]}]},{"title":"西部大开发中的能源资源安全","uses":[{"unit":"Q2","role":"直接考查","use":"本题为选非题。C项所述重点领域安全保障要求表述正确。西部地区产业转型升级应以发展特色优势产业为主攻方向，A项将主攻方向写成全面发展新兴产业，故选A。","evidence":"要坚持统筹发展和安全，提升能源资源等重点领域安全保障能力","qids":["国考 2025 行政执法 行测#20"]}]}],"sources":[{"id":"9317b72d8b159e70","label":"统筹发展和安全","topic":"党政制度与理论","category":"非时政","text":"2.统筹发展和安全\n“坚持统筹发展和安全”，是党的二十届四中全会提出“十五五”时期我国经济社\n会发展必须遵循的六条原则之一，凸显新形势下将安全发展贯穿国家发展各领域、全过程\n的重要性、迫切性。\n发展和安全犹如一体之两翼、驱动之双轮，相辅相成、互为条件，任何时候都不能偏\n废。一方面，发展是解决我国一切问题的基础和关键，不发展是最大的不安全；另一方面，\n安全是发展的前提，没有高水平安全就没有高质量发展。筑牢治国安邦的根基、增强攻坚\n克难的底气，发展是硬道理，安全也是硬道理。","source":{"doc":"41195a191a57c1c36332","first":22,"last":22,"page":22,"file":"《中国共产党第二十届中央委员会第五次全体会议公报》解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#50":{"paper":"政治理论必刷100题","n":50,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",15],"asrc":["国省考政治理论必刷100题.pdf",63],"card":"248169f283e45fe23ed4f982","links":[{"id":"k-cd27115c75d73688","role":"直接考查","why":"讲话要求谋划“十五五”时更加注重统筹发展和安全，并以高效能治理促进两者良性互动。"}]},"国考 2025 行政执法 行测#20":{"paper":"国考 2025 行政执法 行测","n":20,"mod":"政治理论","src":["d8efe4e19862104d89c8.pdf",3],"asrc":["e2c4b1970d2b49eac0fd.pdf",7],"card":"d7084b5b64b0c57a6090095a","links":[{"id":"k-cd27115c75d73688","role":"直接考查","why":"题目考查这一要求在西部大开发中的具体落实，包括提升能源资源等重点领域的安全保障能力。"}]}},"terms":{},"references":{"run":{"name":"习近平主持召开部分省区市“十五五”时期经济社会发展座谈会_中央网络安全和信息化委员会办公室","url":"https://www.cac.gov.cn/2025-04/30/c_1747719103004126.htm"}},"topics":[{"slug":"modern","title":"中国式现代化与民生"}],"units":{"k-cd27115c75d73688":[["政治理论必刷100题#50"],["国考 2025 行政执法 行测#20"]]}};
